import{_ as s,o as e,c as a,a3 as t}from"./chunks/framework.B8xISX-C.js";const k=JSON.parse('{"title":"Dependencies and compatibility","description":"","frontmatter":{"title":"Dependencies and compatibility"},"headers":[],"relativePath":"guide/dependencies.md","filePath":"guide/dependencies.md"}'),n={name:"guide/dependencies.md"};function o(h,i,d,l,p,r){return e(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="dependencies-and-compatibility" tabindex="-1">Dependencies and compatibility <a class="header-anchor" href="#dependencies-and-compatibility" aria-label="Permalink to &quot;Dependencies and compatibility&quot;">​</a></h1><p>This page covers how a mod names other mods it needs, orders itself after them or refuses to run with them.</p><h2 id="dependency-entries" tabindex="-1">Dependency entries <a class="header-anchor" href="#dependency-entries" aria-label="Permalink to &quot;Dependency entries&quot;">​</a></h2><p><code>dependencies</code> in <code>mod.json</code> holds at most 32 entries. Each entry is <code>{ &quot;id&quot;, &quot;range&quot;, &quot;kind&quot; }</code>.</p><ul><li><code>id</code> is the other mod&#39;s id.</li><li><code>range</code> is a version range: <code>*</code>, <code>1.2.3</code>, <code>^1.2.0</code>, <code>~1.2.0</code> or <code>&gt;=1.0.0 &lt;2.0.0</code>. It defaults to <code>*</code>.</li><li><code>kind</code> is <code>required</code>, <code>optional</code> or <code>incompatible</code>.</li></ul><h3 id="required" tabindex="-1">required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;required&quot;">​</a></h3><p>The mod cannot run without the other one.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;carina-team.prism-optics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;range&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li>If the other mod is not switched on in the same game, the game reports <code>missing-dependency</code>.</li><li>If it is switched on but out of range, the game reports <code>dependency-version</code>.</li><li>Switching the mod on in RULES switches its installed required mods on, and theirs in turn.</li><li>In ONLINE CATALOG, INSTALL installs the missing required mods from the catalog with the mod. The detail pane lists them under <code>Also installs: &lt;mods&gt;</code>.</li></ul><h3 id="optional" tabindex="-1">optional <a class="header-anchor" href="#optional" aria-label="Permalink to &quot;optional&quot;">​</a></h3><p>The mod works with or without the other one.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acme.extra&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;optional&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li>If the other mod is absent, nothing happens.</li><li>If it is switched on, it must be in range (<code>dependency-version</code> otherwise), and it loads first.</li></ul><h3 id="incompatible" tabindex="-1">incompatible <a class="header-anchor" href="#incompatible" aria-label="Permalink to &quot;incompatible&quot;">​</a></h3><p>The mod cannot share a game with the other one.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acme.other-mod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;range&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;incompatible&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>If the other mod is switched on and in range, the game reports the error <code>incompatible</code>.</p><h2 id="loadafter" tabindex="-1">loadAfter <a class="header-anchor" href="#loadafter" aria-label="Permalink to &quot;loadAfter&quot;">​</a></h2><p><code>loadAfter</code> is a list of mod ids in <code>mod.json</code>. It orders two mods that are both on and adds no requirement.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;loadAfter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;carina-team.prism-optics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><h2 id="load-order" tabindex="-1">Load order <a class="header-anchor" href="#load-order" aria-label="Permalink to &quot;Load order&quot;">​</a></h2><p>The phase orders the load: the game&#39;s rules, then the profile, then <code>content</code>, <code>patch</code> and <code>final</code> mods. Within a phase, mods load in dependency and <code>loadAfter</code> order, then by id. The RULES picker shows the order.</p><p>A <code>patch</code> mod therefore sees every record of every <code>content</code> mod. That is what a compatibility add-on needs.</p><h2 id="conflicts" tabindex="-1">Conflicts <a class="header-anchor" href="#conflicts" aria-label="Permalink to &quot;Conflicts&quot;">​</a></h2><p>Two mods conflict when nothing orders them (no dependency, no <code>loadAfter</code>, the same phase) and both <code>set</code> the same path. They also conflict when one removes a record the other changes. The RULES picker asks the player to pick a winner. List operations from several mods combine.</p><p>Declare a dependency or <code>loadAfter</code> when your mod builds on another, and the conflict does not arise.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p><a href="/carina-mod-template/examples/choir-prisms">Choir Prisms</a> is a compatibility add-on. It has no records, pictures or text, only patch rows. It requires Prism Optics and Hollow Choir and loads after both. It gives empires that have the Resonance pick Refractive Optics at the Average start. Prism Optics gives that field to everyone at Advanced and keeps it out of Post-Warp, so the example has no Post-Warp row:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;append&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;catalog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;start-state&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;classic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;levels.average.alsoKnown&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;field&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;carina_team.prism_optics.refractive_optics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;when&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;picks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;carina_team.hollow_choir.resonance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A game with all four mods composes in the order <code>carina.base</code>, <code>carina.profile.standard</code>, <code>carina-team.hollow-choir</code>, <code>carina-team.prism-optics</code> (unrelated, so by id) and <code>carina-team.choir-prisms</code>.</p><h2 id="finding-dependencies-when-testing" tabindex="-1">Finding dependencies when testing <a class="header-anchor" href="#finding-dependencies-when-testing" aria-label="Permalink to &quot;Finding dependencies when testing&quot;">​</a></h2><p><code>check</code>, <code>run</code> and <code>pack</code> look for the mods a folder requires in the other folders of <code>mods/</code>. To name a folder elsewhere, add <code>--with &lt;folder&gt;</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> carina-modkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mods/choir-prisms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> carina-modkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../elsewhere/my-add-on</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mods/prism-optics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mods/hollow-choir</span></span></code></pre></div><p>The <a href="/carina-mod-template/check">Check my mod</a> page checks one mod at a time, so it reports a required mod as missing.</p>`,34)])])}const E=s(n,[["render",o]]);export{k as __pageData,E as default};
